    //
    document.addEventListener('DOMContentLoaded', () => {

      /* --- MODO NOTURNO --- */
      const htmlEl = document.documentElement;
      const themeBtn = document.getElementById('darkModeToggle');
      const setTheme = (t) => {
        htmlEl.setAttribute('data-bs-theme', t);
        localStorage.setItem('magTheme', t);
        const icon = document.getElementById('themeIcon');
        if(icon) icon.className = t === 'dark' ? 'bi bi-sun-fill text-warning' : 'bi bi-moon-stars-fill text-dark';
      };
      setTheme(localStorage.getItem('magTheme') || 'light');
      if(themeBtn) themeBtn.onclick = () => setTheme(htmlEl.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark');

      /* --- SLIDER (JSON) --- */
      const sCont = document.getElementById('hero-slider-container');
      if(sCont) {
        fetch('/feeds/posts/default?alt=json&max-results=4').then(r => r.json()).then(d => {
          let h = '<div class="main-hero-slider">';
          (d.feed.entry || []).forEach(e => {
            const title = e.title.$t; 
            let link = '#'; e.link.forEach(l => { if(l.rel==='alternate') link=l.href; });
            let img = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s[0-9]+(\-c)?\//, '/w1200-h600-c/') : 'https://placehold.co/1200x600/1e293b/FFF?text=Tech';
            h += `<div class="hero-slider-item"><img src="${img}" class="hero-slider-img"><div class="hero-overlay"><span class="badge bg-primary mb-3 align-self-start">Destaque</span><h2 class="h2 fw-bold"><a href="${link}" class="text-white text-decoration-none">${title}</a></h2></div></div>`;
          });
          h += '</div>';
          sCont.innerHTML = h;
          if(typeof tns !== 'undefined') {
            tns({ container: '.main-hero-slider', items: 1, autoplay: true, autoplayButtonOutput: false, controls: false, nav: false, mouseDrag: true });
          }
        });
      }

      /* --- AJAX PAGINAÇÃO --- */
      const lmBtn = document.getElementById('ajax-load-more');
      const pGrid = document.getElementById('post-grid');
      if(lmBtn && pGrid) {
        lmBtn.onclick = function(e) {
          e.preventDefault(); const url = this.href; const origText = this.innerHTML;
          this.innerHTML = '<span class="spinner-border spinner-border-sm"></span>'; this.style.pointerEvents = 'none';
          fetch(url).then(r => r.text()).then(html => {
            const doc = new DOMParser().parseFromString(html, 'text/html');
            doc.querySelectorAll('#post-grid .post-item').forEach(p => pGrid.appendChild(p));
            const nP = doc.getElementById('ajax-load-more');
            if(nP) { this.href = nP.href; this.innerHTML = origText; this.style.pointerEvents = 'auto'; } 
            else { this.parentElement.remove(); }
          });
        };
      }

      /* --- ARTIGOS RELACIONADOS --- */
      const rCont = document.getElementById('related-posts-container');
      if(rCont) {
        const label = rCont.getAttribute('data-label');
        if(label) {
          fetch(`/feeds/posts/default/-/${encodeURIComponent(label)}?alt=json&max-results=3`).then(r => r.json()).then(d => {
            let h = '<h3 class="h5 fw-bold mb-4">Leia Também</h3><div class="row g-4">';
            (d.feed.entry || []).forEach(e => {
              const title = e.title.$t; let link = '#'; e.link.forEach(l => { if(l.rel==='alternate') link=l.href; });
              if(window.location.href.indexOf(link) === -1) {
                let img = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s[0-9]+(\-c)?\//, '/w400-h250-c/') : 'https://placehold.co/400x250/e2e8f0/FFF?text=News';
                h += `<div class="col-md-4"><article class="news-card"><a href="${link}"><img src="${img}" class="news-img" style="height:150px;"></a><div class="p-3"><h4 class="h6 fw-bold mb-0"><a href="${link}" class="text-body text-decoration-none">${title}</a></h4></div></article></div>`;
              }
            });
            h += '</div>';
            rCont.innerHTML = h;
          });
        }
      }
    });

/* --- MOTOR DO MENU DINÂMICO (DROPDOWN COM UNDERLINE _) --- */
      const menuList = document.getElementById('mag-dynamic-menu');
      if (menuList) {
        const items = Array.from(menuList.querySelectorAll('.mag-menu-item'));
        let currentParent = null;
        let currentDropdownMenu = null;

        items.forEach(item => {
          const link = item.querySelector('a');
          const text = link.textContent.trim();

          // Se a palavra começar com _ (Underline)
          if (text.startsWith('_')) {
            link.textContent = text.substring(1).trim(); // Remove o underline da tela
            link.classList.remove('nav-link');
            link.classList.add('dropdown-item');

            if (currentParent) {
              // Se ainda não criou a caixa do dropdown, cria agora
              if (!currentDropdownMenu) {
                currentParent.classList.add('dropdown');
                const parentLink = currentParent.querySelector('a.nav-link');
                parentLink.classList.add('dropdown-toggle');
                parentLink.setAttribute('data-bs-toggle', 'dropdown'); // Para funcionar no mobile

                currentDropdownMenu = document.createElement('ul');
                currentDropdownMenu.className = 'dropdown-menu border-0';
                currentParent.appendChild(currentDropdownMenu);
              }
              // Move este item para dentro da caixa do menu suspenso
              item.classList.remove('nav-item');
              item.style.listStyle = 'none';
              currentDropdownMenu.appendChild(item);
            }
          } else {
            // Se for um link normal, ele vira o novo "Pai"
            currentParent = item;
            currentDropdownMenu = null; 
          }
        });
      }
    //








    //
    (function() {
      const btnTopo = document.getElementById('btnVoltarTopo');
      if (!btnTopo) return;

      // Função que verifica o scroll de forma global (segura para todos os browsers)
      window.addEventListener('scroll', function() {
        const rolagem = window.scrollY || document.documentElement.scrollTop;
        if (rolagem > 300) {
          btnTopo.style.opacity = '1';
          btnTopo.style.visibility = 'visible';
          btnTopo.style.transform = 'translateY(0)';
        } else {
          btnTopo.style.opacity = '0';
          btnTopo.style.visibility = 'hidden';
          btnTopo.style.transform = 'translateY(20px)';
        }
      });

      // Função de subida suave
      btnTopo.addEventListener('click', function() {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });

      // Efeito de hover via JS (para evitar misturar com o CSS principal)
      btnTopo.addEventListener('mouseover', () => { btnTopo.style.transform = 'translateY(-5px) scale(1.1)'; });
      btnTopo.addEventListener('mouseout', () => { 
        if (window.scrollY > 300) btnTopo.style.transform = 'translateY(0) scale(1)'; 
      });
    })();
    // Achado: bloco "MOTOR DO PRELOADER" (window.addEventListener('load', ...))
    // removido daqui — já coberto pelo campo 'js' da peça widget 'preloader'
    // (protegida, renderizada via NICHO_WIDGETS_HTML, token), evitando
    // duplicar o mesmo listener.
    //



    //
    document.addEventListener('DOMContentLoaded', function() {
      // Procura o cartão de destaque na página
      const cartaoDestaque = document.querySelector('.FeaturedPost .post-summary');

      if (cartaoDestaque) {
        const imagem = cartaoDestaque.querySelector('.image');
        const titulo = cartaoDestaque.querySelector('h3');
        const resumo = cartaoDestaque.querySelector('p');

        // Garante que o título tem um link para podermos extrair
        const linkTitulo = titulo ? titulo.querySelector('a') : null;

        // 1. REORDENAÇÃO FÍSICA DO DOM
        // Pega na imagem (que estava no fundo) e injeta-a como o 1º elemento do cartão
        if (imagem) {
          cartaoDestaque.insertBefore(imagem, cartaoDestaque.firstChild);
        }

        // 2. INJEÇÃO DO BOTÃO "LER ARTIGO"
        if (linkTitulo && resumo) {
          const urlArtigo = linkTitulo.href;

          // Cria o botão virtualmente
          const btnLer = document.createElement('a');
          btnLer.href = urlArtigo;
          btnLer.className = 'btn btn-primary mt-3 rounded-pill fw-bold text-uppercase d-inline-flex align-items-center justify-content-center';
          btnLer.style.fontSize = '0.75rem';
          btnLer.style.letterSpacing = '1px';
          btnLer.style.padding = '10px 20px';
          btnLer.style.alignSelf = 'flex-start'; // Alinha à esquerda
          btnLer.style.marginLeft = '20px';
          btnLer.style.marginBottom = '20px';
          btnLer.innerHTML = 'Ler Artigo <i class="bi bi-arrow-right ms-2 fs-6"></i>';

          // Adiciona o botão logo a seguir ao texto do resumo
          cartaoDestaque.appendChild(btnLer);

          // Ajusta o padding do resumo para o botão não ficar colado
          resumo.style.paddingBottom = '5px';
        }
      }
    });
    //



//
document.addEventListener('DOMContentLoaded', function() {
    const popular = document.querySelector('.PopularPosts');
    if (!popular) return;

    const list = popular.querySelector('ul');
    const items = list.querySelectorAll('li');

    // 1. CONSTRUÇÃO DAS ABAS (INTERFACE)
    const tabs = document.createElement('div');
    tabs.className = 'popular-tabs';
    tabs.innerHTML = `
        <button class="tab-btn active" data-filter="all">Trending</button>
        <button class="tab-btn" data-filter="hot">Hot 🔥</button>
        <button class="tab-btn" data-filter="new">Top</button>
    `;
    popular.querySelector('.widget-content').prepend(tabs);

    // 2. MOTOR DO TERMÔMETRO
    items.forEach((item, i) => {
        const link = item.querySelector('a');
        if (link) {
            const barWrap = document.createElement('div');
            barWrap.className = 'hotness-container';
            const percent = ((items.length - i) / items.length) * 100;
            barWrap.innerHTML = `<div class="hotness-bar" style="width: 0%"></div>`;
            link.after(barWrap);
            setTimeout(() => { 
                const bar = barWrap.querySelector('.hotness-bar');
                if(bar) bar.style.width = percent + '%';
            }, 600);
        }
    });

    // 3. MOTOR DO CARROSSEL (INFINITO SUAVE)
    let pos = 0;
    const step = 105; // 95px de altura + 10px de margin
    const visible = 4;

    function startCarousel() {
        if (popular.matches(':hover')) return; // Pausa no Hover

        pos++;
        if (pos > items.length - visible) {
            pos = 0; // Reinício suave
        }
        list.style.transform = `translateY(-${pos * step}px)`;
    }

    if (items.length > visible) {
        setInterval(startCarousel, 4000);
    }

    // 4. LÓGICA DAS ABAS (SIMULAÇÃO DE FILTRO)
    tabs.addEventListener('click', (e) => {
        if (e.target.classList.contains('tab-btn')) {
            tabs.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            e.target.classList.add('active');
            // Efeito visual de refresh na lista
            list.style.opacity = '0.5';
            setTimeout(() => list.style.opacity = '1', 300);
        }
    });
});
//



//
document.addEventListener('DOMContentLoaded', function() {
  // Configuração do Observador
  const observerOptions = {
    threshold: 0.15 // Ativa quando 15% do elemento estiver visível
  };

  const revealObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('active');
        // Opcional: parar de observar após animar uma vez
        // observer.unobserve(entry.target); 
      }
    });
  }, observerOptions);

  // Seleciona todos os elementos que queremos animar
  const elementsToReveal = document.querySelectorAll('.mag-reveal, .reveal-left, .reveal-right');

  elementsToReveal.forEach(el => {
    revealObserver.observe(el);
  });
});
//



//
document.addEventListener('DOMContentLoaded', function() {
    const pageLinks = document.querySelectorAll('.PageList li a');
    const currentUrl = window.location.href.split(/[?#]/)[0]; // Pega a URL limpa

    pageLinks.forEach(link => {
        // Se a URL do link for igual à URL atual, marca como ativo
        if (link.href === currentUrl || (currentUrl.endsWith('/') && link.href.endsWith('/'))) {
            link.classList.add('active');
            link.parentElement.classList.add('selected');
        }
    });
});
//



//
document.addEventListener('DOMContentLoaded', function() {
    // Monitora a renderização do tradutor
    const checkTranslate = setInterval(() => {
        const combo = document.querySelector('.goog-te-combo');
        if (combo) {
            combo.parentElement.classList.add('mag-translate-loaded');
            clearInterval(checkTranslate);
        }
    }, 500);
});
